"""Package validated Aqua v10 action casts and four exact Test 2 combo sets."""
from pathlib import Path
import csv,hashlib,json,shutil,sys,zipfile
from aqua_v10_plan import SETS,BANK
ROOT=Path(__file__).resolve().parents[1]
DEST=ROOT/'KH1FM_Aqua_Animation_Test_v10'

README="KH1FM AQUA ANIMATION TEST v10 - TEST 2\nSteam Global / OpenKH Panacea\n\nMAIN AQUA ACTIONS\nAction                   Ground source   Air source\nFire                     316             391\nThunder                  317             390\nCure                     318             427\nFalling                  506\n\nFire uses one continuous source clip through KH1's release/recovery records:\n316 frames 0..20 then 20..30; 391 frames 0..31 then 31..48.\n506 replaces falling only. Jump takeoff/rise and landing keep their V9 poses.\nThe original aqua ground/air combos remain the same as V9.\n\nFIVE ABILITIES, ALL 0 AP\naqua   : main Aqua moveset, with the action assignments above\naqua 1 : Test 2 ground 392 393 428 ; air 429 504 514\naqua 2 : Test 2 ground 515 517 550 ; air 650 557 411\naqua 3 : Test 2 ground 399 352 353 ; air 500 501 503\naqua 4 : Test 2 ground 510 511 512 ; air 513 507 508\n\nThe numbered entries inherit the main movement, falling, casting, items,\nreactions, Guard and Cartwheel. Only their ground/air combo sets differ.\nThe first clip is attack one, the second attack two, the third the finisher.\nKH1's alternate second ground attack also uses the selected second clip.\nSelecting a new Aqua entry turns the other Aqua entries off. Native ability\nstates are retained. Select while idle; active actions finish before switching.\nAbility ids117..121 and saved selections remain compatible with V9.\n\nSHARED KH1 CAST RECORDS\nNative KH1 dispatch is ground request 0x36 + spell index, air 0x83 + index.\nFire=0, Blizzard=1, Thunder=2, Cure=3, Gravity=4, Stop=5, Aero=6.\nThunder and Cure normally share a physical animation record. While any Aqua\nentry is active, an actor-local copy of the existing request table routes only\nThunder requests 0x38/0x85 to the alternate casting record. Cure keeps 0x39/0x86.\nAll other request words/flags, table sizes, record counts and original tables\nstay intact. Unequipping Aqua restores the exact original lookup pointer.\nNo new native-code hook is used for this cast separation.\n\nBlizzard/Gravity share 317 on the ground and 390 in the air. Stop/Aero share\n318 on the ground and 427 in the air. These inherited poses are intentional\nfor this test; the spells still run their native KH1 effects and game logic.\nThunder now uses that alternate record's native duration: 86 ground frames\nand 78 air frames, instead of 68/68. Its cast/recovery timing needs an in-game\ncheck. Other record durations stay as V9. This is an animation test; the BBS\nclips' original durations are resampled to the selected KH1 records.\n\nRETAINED CORRECTIONS\n- Anatomical hand pivots100/205 and forearm-helper alignment from V9.\n- Original main-combo finisher arm-clearance adjustment from V9.\n- Hair rest rotations from V8; no animated anatomical stretch or scale.\n- Working native spell-origin and glow/effect-matrix route to the LEFT palm206\n  in all five profiles. The prior right-hand route has not been reinstated.\n\nINSTALL\n1. Fully close KH1.\n2. Disable Aqua v9 and all older Aqua packages, Sora Restore Check, and\n   Nine Styles / Dual Wield. Keep other Sora model/moveset replacements off.\n3. Import this ZIP into OpenKH and enable Aqua Animation Test v10.\n4. Build and Run, then load your save. Missing Aqua entries are added off;\n   a saved selection is respected. Native entries are never evicted to fit.\n5. Equip aqua or one of aqua 1..4 while standing idle. The main aqua entry\n   does not need to be equipped along with a numbered entry.\n\nTEST\n- With aqua equipped, check Fire, Thunder and Cure on the ground and in the\n  air. Check spell release, recovery and the LEFT-hand launch/glow alignment.\n- Step off a ledge and check 506 during falling. Check jumps/landing as well.\n- Switch through aqua 1..4 while idle and test three-hit ground/air combos.\n  Unequip Slapshot, Sliding Dash, Vortex, Hurricane Blast and other native\n  combo replacements for a clean test; their separate actions stay native.\n  Guard and Dodge Roll still need their native abilities equipped.\n- Turn every Aqua entry off and recheck native casting. Repeat after room\n  changes and after save reloads on both saves.\n\nRETURN\nReturn the NEW kh1-aqua.log beside the game EXE and a short comparison video.\nIts first line must say ANIMATION TEST v10 Test 2. Profile numbers in the log:\n0=native, 1=aqua, 2=aqua 1, 3=aqua 2, 4=aqua 3, 5=aqua 4.\nAQUA CAST REQUESTS reports enabling/restoring the separated Thunder lookup.\nCHECK_AQUA_V10.cmd optionally checks installation hashes and writes\nAqua_Animation_Check_v10.txt.\n\nSCOPE\nKH1 damage, targeting, projectile scripts, spell simulation, MP, guard coverage,\ndodge invincibility and actor travel remain native. Native attachment queries\nuse the left hand during eligible Aqua casts. BBS commands, damage and effects\nare not imported. Guard uses the Barrier pose with KH1 Guard behavior.\nBoth installed MSET files are original. Motion poses use only existing table\nallocations; all motion headers, counts, lengths and eleven helpers remain\noriginal. Unknown/foreign body records or request tables block writes.\nOnly the supplied normal Sora and Olympus banks are admitted.\n\nFILE GUIDE\nABILITY_SETS.txt gives exact Test 2 combos.\nANIMATION_MAP.csv lists all five profiles' effective action assignments.\nTEST_CLIP_SOURCES.csv gives the new casts/falling and Test 2 source banks,\nframe counts, payload hashes and fitted slots. 399 uses p02ex_346.arc,\n353 uses p02ex_352.arc, and 411 uses p02ex_313.arc (dedicated source banks).\nThese numbered labels are not assumed to be official BBS command names.\nREMAINING_NATIVE.csv lists unassigned native records.\nThe earlier 349-clip CSV/JSON inventory is included under inventory. Its\nsource metadata is unchanged; ANIMATION_MAP.csv has current assignments.\n\nOPTIONAL NATIVE-MAGIC ATTACHMENTS\nCopy DISABLE_HAND_MAGIC_kh1-aqua.ini beside the game EXE as kh1-aqua.ini and\nrestart to retain native weapon-tip attachments with these animation poses.\nRemove that INI and restart to restore left-hand attachment routing. This\noption does not disable the separated Thunder animation lookup.\n\nSAVE / REMOVE ALL AQUA ENTRIES\nSaving in-game may retain ids117..121. To remove them, copy\nREMOVE_AQUA_kh1-aqua.ini beside the game EXE as kh1-aqua.ini, leave v10 enabled,\nrestart and load each save to clean. Check AQUA ABILITIES REMOVED, then save\nin-game. Exit, remove the INI, disable v10 and rebuild. Native ability order\nis preserved; only these five ids are removed.\n\nVALIDATION\n38 tests execute the compiled PE DLL in a Win64 ABI mock host. They include\nall five profiles in both banks, exact action lookup mappings, only two changed\nrequest words, original lookup/body restoration, reloads, exclusivity, removal,\nforeign-data rejection and the distinct left-palm attachment route.\n14 geometry/assignment tests cover all 75 generated records, native capacities,\nhair, wrist helpers, bind lengths/scales, Fire phase continuity, looping fall,\njump transitions and the retained main-finisher clearance adjustment.\nThese checks do not render Sora's mesh or execute Windows/KH1. The new cast\nrouting and timing, source-clip appearance and final FX alignment need your\nin-game check. Some mesh clipping may still need adjustment.\n"

SOURCE="AQUA V10 TEST 2 SOURCE\n\nNormal installation requires OpenKH/Panacea; these are development files.\n\nDLL BUILD / EXECUTION CHECK (Linux x64)\n  python3 generate_data.py\n  python3 build.py\n  python3 test_runtime.py\n  python3 test_visuals.py\nGCC, GNU ld with i386pep support and Python are needed. Geometry checks also\nneed NumPy/SciPy. Runtime tests map the final PE and execute its real exports\nand attachment detours against Win64 ABI mocks, not Windows or KH1.\n\nREBUILD POSES (optional; NumPy, SciPy, Pillow)\nFrom this source directory:\n  python3 retargeting/tools/build_aqua_complete_v10.py --profile 0 --output .\n  python3 retargeting/tools/build_aqua_complete_v10.py --profile 1 --output sets/p1\n  python3 retargeting/tools/build_aqua_complete_v10.py --profile 2 --output sets/p2\n  python3 retargeting/tools/build_aqua_complete_v10.py --profile 3 --output sets/p3\n  python3 retargeting/tools/build_aqua_complete_v10.py --profile 4 --output sets/p4\n  python3 generate_data.py\n  python3 build.py\n  python3 test_runtime.py\n  python3 test_visuals.py\n--slots followed by normal slot numbers rebuilds only those records in a\nprofile. Required source ARC files are in retargeting/core_source. Original\nMSET files are ../assets. Immutable baseline sampling caches are reproducible\nand are not distributed. V9 anatomical refinements are retained and applied once to each baseline.\n\nANATOMICAL WRIST PIVOTS\naqua_refine_v9.py keeps Sora's distal forearm helper angles at bind and applies\nthe hand's authored orientation at pivots100/205. Arm solves rotate the whole\ndistal forearm together and preserve the hand's orientation at that pivot.\nFinisher clearance checks include interior arm samples. All local anatomical\noffsets/scales retain their bind values. The V8 reference contains 41 samples\nof ten joints per original converted motion; it supports an independent\nbefore/after comparison of serialized forearm clearance. It is not mesh\ncollision detection. Hair155..193 retains the v8 bind-rest correction.\n\nFIVE PROFILE GATE\nThe generated header stores original tables and five immutable after sets.\nUnchanged profile blocks are shared. All 47/46 records are admitted against\nthe known original/base/test sets before any writes. Selection changes wait\nfor idle. Ability ids117..121 are 0 AP. Newly enabled Aqua entries win and\nonly other Aqua entries are turned off. Missing entries are granted only if\nall fit with a terminator in the original 48-byte list. Native entries are\nnot evicted. Uninstall removes only ids117..121.\n\nACTION CAST LOOKUP\nNative Steam command handlers dispatch ground magic with 0x36+spell and air\nmagic with 0x83+spell. Thunder is index2, Cure index3. The supplied MSETs share\ntheir physical record. aqua_cast_requests.h changes actor+1D8 to an immutable\n1408-byte request copy while a verified Aqua profile is active. Only Thunder\nmoves to the alternate casting family (normal55/80, Olympus18/42); all other\nrequest words and native flags remain. The original table is never written.\nNative resolver0x2A01E0 reads that field (+8 from actor+1D0). All body and\nrequest destinations must pass admission before writes; idle-only switching,\nper-bank original pointers, foreign-pointer rejection and exact restoration\nare tested. cast_request_validation.json records native instruction evidence\nfrom the supplied executable. No new entry-point detour is used here.\nThunder therefore uses 86 ground / 78 air frames, instead of the shared\n68/68 frames. Native per-record event tracks stay intact. Final spell timing\nhas not been tested in KH1. Blizzard/Gravity inherit317/390; Stop/Aero318/427.\n\nLEFT-HAND MAGIC\nThe two native entry points and admitted instruction spans are unchanged from\nv8. Their direct matrix selector is now0x20CE, the LEFT palm206, in all five\nprofiles. Native cast requests, current actor/bank, event/script exclusions\nand native fallthrough are retained. No spell-resource or projectile script\nis replaced. The supplied executable is not included; its original hash and\nthe entry spans are in native_attachment_validation.json.\n\nCAPACITY / SOURCE IDS\nNo motion/header/table expansion is used. The cast lookup copy has the original\n352 request words; only Thunder entries0x38/0x85 change their physical slot. The original eleven helpers and\nnative travel remain. Four sets change seven physical combo records each:\nC8 first, C9/CA second, CB finisher, CC first air, CD second air, CE finisher.\nThe donor selection is in aqua_v10_plan.py. Numeric IDs retain their exact\nsource bank/hash in TEST_CLIP_SOURCES.csv; no command names are inferred.\nThe source inventory files under ../inventory retain v8's source metadata.\nCurrent ability mappings are ../ANIMATION_MAP.csv.\n\nExisting upstream licenses and notices are retained in licenses.\nFormat reference: https://openkh.dev/bbs/file/type/pam.html\n"

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()

def build():
    d=ROOT/'ability_v10';runtime=json.loads((d/'runtime_validation.json').read_text());geometry=json.loads((d/'visual_validation.json').read_text())
    reports=[json.loads((d/'curve_validation.json').read_text())]+[json.loads((d/f'sets/p{i}/curve_validation.json').read_text()) for i in range(1,5)]
    assert runtime['passed'] and geometry['passed'] and all(r['passed'] for r in reports)
    shutil.copytree(ROOT/'KH1FM_Aqua_Animation_Test_v9',DEST,dirs_exist_ok=True)
    for p in [DEST/'CHECK_AQUA_V9.cmd',DEST/'Check_Aqua_Animations_v9.ps1',DEST/'inventory/Aqua_Move_Inventory_v8.xlsx']:
        p.unlink(missing_ok=True)
    for n in ['aqua.c','aqua_magic.h','aqua_cast_requests.h','aqua_data.h','build.py','generate_data.py','test_runtime.py','test_bridge.c','test_visuals.py',
              'curve_validation.json','data_validation.json','runtime_validation.json','visual_validation.json','arm_alignment_validation.json','cast_request_validation.json']:
        shutil.copy2(d/n,DEST/'source'/n)
    (DEST/'source/clearance_validation.json').unlink(missing_ok=True)
    (DEST/'source/spreadsheet_validation.json').unlink(missing_ok=True)
    shutil.copytree(d/'fixtures',DEST/'source/fixtures',dirs_exist_ok=True)
    shutil.copytree(d/'sets',DEST/'source/sets',dirs_exist_ok=True)
    shutil.copy2(d/'kh1-aqua.dll',DEST/'dll/kh1-aqua.dll')
    tools=DEST/'source/retargeting/tools'
    for name in ['build_aqua_complete_v10.py','aqua_refine_v9.py','aqua_v10_plan.py','aqua_refine_v8.py','package_aqua_v10.py']:
        shutil.copy2(ROOT/'tools'/name,tools/name)
    for number in sorted(set(BANK.values())):
        name=f'p02ex_{number}.arc';shutil.copy2(ROOT/'capture_20261101/Sources/data/bbs/arc/pc'/name,DEST/'source/retargeting/core_source'/name)
    (DEST/'README_FIRST.txt').write_text(README);(DEST/'source/README_SOURCE.txt').write_text(SOURCE)
    desc='Test 2: aqua uses Fire316/391, Thunder317/390, Cure318/427 and fall506; aqua 1..4 select four new ground/air combo sets. Keeps wrist/hair corrections and LEFT-hand magic. Steam Global / Panacea; disable earlier Aqua packages and Nine Styles / Dual Wield.'
    manifest=(ROOT/'KH1FM_Aqua_Animation_Test_v9/mod.yml').read_text();start=manifest.index('description:');end=manifest.index('assets:')
    manifest=manifest[:start]+'description: >-\n  '+desc+'\n'+manifest[end:]
    (DEST/'mod.yml').write_text(manifest.replace('Animation Test v9','Animation Test v10'))
    checker=(ROOT/'KH1FM_Aqua_Animation_Test_v9/Check_Aqua_Animations_v9.ps1').read_text().replace('v9','v10').replace('CHECK_AQUA_V9','CHECK_AQUA_V10')
    (DEST/'Check_Aqua_Animations_v10.ps1').write_text(checker)
    (DEST/'CHECK_AQUA_V10.cmd').write_bytes(b'@echo off\r\nsetlocal\r\npowershell.exe -NoLogo -NoProfile -ExecutionPolicy Bypass -File "%~dp0Check_Aqua_Animations_v10.ps1" %*\r\npause\r\n')
    (DEST/'REMOVE_AQUA_kh1-aqua.ini').write_text('[aqua]\nremove_aqua=1\nhand_magic=0\n')
    (DEST/'DISABLE_HAND_MAGIC_kh1-aqua.ini').write_text('[aqua]\nremove_aqua=0\nhand_magic=0\n')
    labels=['aqua']+[f'aqua {i}' for i in range(1,5)]
    (DEST/'ABILITY_SETS.txt').write_text('\n'.join([f'Ability {label} / id{117+i} / 0 AP' + (' / main set; Fire316/391 Thunder317/390 Cure318/427 Fall506' if not i else f' / ground {" ".join(SETS[i-1][0])} / air {" ".join(SETS[i-1][1])}') for i,label in enumerate(labels)])+'\n\nSelect one while idle. Other Aqua entries turn off automatically.\n')
    maps=[];sources=[]
    sys.path.insert(0,str(ROOT/'tools'));from bbs_source_inspector import read_arc,read_pam
    import struct
    for profile in range(5):
        active={r['normal_slot']:r for r in reports[0]['motions']}
        if profile:active.update({r['normal_slot']:r for r in reports[profile]['motions']})
        for r in sorted(active.values(),key=lambda x:x['normal_slot']):
            maps.append({'Ability':labels[profile],'Ability id':117+profile,'Action':r['action'],'Native request':f'0x{r["request"]:02X}',
                'Normal slot':r['normal_slot'],'Olympus slot':r['olympus_slot'] if r['olympus_slot']!=0xffffffff else 'not present',
                'Aqua clip':r['donor'],'Source bank':r['source_bank'],'Source frame range':str(r['source_range']) if r['source_range'] else 'full',
                'Pose loop':r['loop'],'Native frames':r['native_frames'],'Root policy':r['root']})
        for r in reports[profile]['motions']:
            if not profile and r['normal_slot'] not in [10,54,55,56,57,79,80,81,82]:continue
            arc=ROOT/'capture_20261101/Sources/data/bbs/arc/pc'/r['source_bank'];members,_=read_arc(arc.read_bytes())
            for member,data in members:
                if not data.startswith(b'PAM\0'):continue
                for a in read_pam(data,54):
                    if a.name!=r['donor']:continue
                    start=struct.unpack_from('<I',data,16+16*a.slot)[0]
                    sources.append({'Ability':labels[profile],'Action':r['action'],'Normal slot':r['normal_slot'],'Source name':a.name,
                        'Source bank':r['source_bank'],'PAM member':member,'Source frames':a.frame_count,'Source FPS':a.fps,'Source frame range':str(r['source_range']) if r['source_range'] else 'full',
                        'Animation SHA256':hashlib.sha256(data[start:a.data_end]).hexdigest(),'Native frames':r['native_frames'],'Native FPS':60})
    for name,rows in [('ANIMATION_MAP.csv',maps),('TEST_CLIP_SOURCES.csv',sources)]:
        with (DEST/name).open('w',newline='',encoding='utf-8-sig') as f:
            w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
    # Keep the old source inventory, but remove its outdated assignment view.
    (DEST/'inventory/Aqua_KH1_Assignments.csv').unlink(missing_ok=True)
    expected={'version':10,'assets':[]}
    for logical,actual in [('dll/kh1-aqua.dll',DEST/'dll/kh1-aqua.dll'),('xa_ex_0010.mset',DEST/'assets/xa_ex_0010.mset'),('xa_ex_0010_he.mset',DEST/'assets/xa_ex_0010_he.mset')]:
        expected['assets'].append({'name':logical,'sha256':sha(actual),'bytes':actual.stat().st_size})
    (DEST/'expected_assets.json').write_text(json.dumps(expected,indent=2)+'\n')
    native=json.loads((DEST/'source/native_attachment_validation.json').read_text());native.pop('direct_right_palm_matrix_selector',None);native.pop('right_palm_index',None)
    native.update({'direct_left_palm_matrix_selector':'0x20CE','left_palm_index':206,'runtime_mock_profiles_tested':5,'windows_or_game_executed':False})
    (DEST/'source/native_attachment_validation.json').write_text(json.dumps(native,indent=2)+'\n')
    all_records=[r for report in reports for r in report['motions']]
    validation={'version':10,'test_round':2,'offline_checks_passed':True,'game_runtime_tested':False,'abilities':labels,'ability_ids':list(range(117,122)),
        'normal_motion_records_per_profile':47,'olympus_motion_records_per_profile':46,'unique_generated_records':len(all_records),
        'actual_pe_mock_tests':runtime['tests'],'geometry_transition_tests':geometry['tests'],'pose_samples':sum(r['validated_pose_samples'] for r in all_records),
        'max_pose_position_fit_error':max(r['max_pose_position_error'] for r in all_records),
        'max_non_root_attachment_translation_error':max(r['max_non_root_attachment_translation_error'] for r in all_records),
        'max_scale_error':max(r['max_scale_error'] for r in all_records),'native_travel_error':max(r['root_helper_error'] for r in all_records),
        'original_motion_lengths_headers_and_counts_preserved':True,'helper_slots':11,'original_msets_on_disk':True,
        'main_actions':{'Fire':[316,391],'Thunder':[317,390],'Cure':[318,427],'Falling':506},
        'test_2_combos':SETS,'cast_request_words_changed':[56,133],
        'thunder_cast_frames':{'ground':86,'air':78,'previous_ground':68,'previous_air':68},
        'left_palm_magic':206,'dll_sha256':sha(DEST/'dll/kh1-aqua.dll'),
        'limitations':['Windows/KH1 execution, rendering and Thunder cast timing of v10 pending','Arm separation uses joint/capsule checks; some mesh clipping may remain',
                       'Numbered clips use native KH1 durations and hit events; BBS commands/effects are not imported']}
    (DEST/'validation.json').write_text(json.dumps(validation,indent=2)+'\n')
    with zipfile.ZipFile(DEST.with_suffix('.zip'),'w',zipfile.ZIP_DEFLATED,compresslevel=9) as z:
        for p in sorted(DEST.rglob('*')):
            if p.is_file() and '__pycache__' not in p.parts:z.write(p,p.relative_to(DEST))
    print(json.dumps({'zip':str(DEST.with_suffix('.zip')),'bytes':DEST.with_suffix('.zip').stat().st_size,'sha256':sha(DEST.with_suffix('.zip')),'validation':validation},indent=2))

if __name__=='__main__':build()
